import {zipStore} from './est.js';
export const sheetXml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c])).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,'');
export function columnName(n){let s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26);}return s;}
export function writeTemplateWorkbook(sheets,styles){
 const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main',rel='http://schemas.openxmlformats.org/officeDocument/2006/relationships',entries={};
 entries['[Content_Types].xml']=`<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`;
 entries['_rels/.rels']=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="${rel}/officeDocument" Target="xl/workbook.xml"/></Relationships>`;
 entries['xl/_rels/workbook.xml.rels']=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${rel}/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length+1}" Type="${rel}/styles" Target="styles.xml"/></Relationships>`;
 entries['xl/styles.xml']=styles;
 const defined=sheets.map((s,i)=>{const name="'"+s.name.replaceAll("'","''")+"'",a=s.printArea,t=s.printTitles;return `<definedName name="_xlnm.Print_Area" localSheetId="${i}">${sheetXml(name+`!$${columnName(a[4]+1)}$${a[2]+1}:$${columnName(a[5])}$${s.rows.length}`)}</definedName>`+(t?`<definedName name="_xlnm.Print_Titles" localSheetId="${i}">${sheetXml(name+`!$${t[2]+1}:$${t[3]}`)}</definedName>`:'');}).join('');
 entries['xl/workbook.xml']=`<workbook xmlns="${ns}" xmlns:r="${rel}"><bookViews><workbookView activeTab="0"/></bookViews><sheets>${sheets.map((s,i)=>`<sheet name="${sheetXml(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets><definedNames>${defined}</definedNames><calcPr calcId="191029" fullCalcOnLoad="1"/></workbook>`;
 for(const [i,s] of sheets.entries()){
  const p=s.print,flags=p.flags||0;
  const data=s.rows.map((row,r)=>`<row r="${r+1}" ht="${row.height}" customHeight="1">${row.styles.map((style,c)=>{const v=row.values[c],ref=columnName(c+1)+(r+1);if(v===undefined||v===null||v==='')return `<c r="${ref}" s="${style}"/>`;if(typeof v==='object'&&v.formula)return `<c r="${ref}" s="${style}"><f>${sheetXml(v.formula)}</f><v>${v.value}</v></c>`;if(typeof v==='number'){if(!Number.isFinite(v))throw Error('엑셀에 저장할 수 없는 금액입니다.');return `<c r="${ref}" s="${style}"><v>${v}</v></c>`;}return `<c r="${ref}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${sheetXml(v)}</t></is></c>`;}).join('')}</row>`).join('');
  entries[`xl/worksheets/sheet${i+1}.xml`]=`<worksheet xmlns="${ns}"><sheetPr><pageSetUpPr fitToPage="${p.fitToPage?1:0}"/></sheetPr><sheetViews><sheetView workbookViewId="0"${s.view==='pageBreakPreview'?' view="pageBreakPreview" zoomScale="85" zoomScaleSheetLayoutView="85"':''} showGridLines="${s.showGridLines?1:0}" showZeros="${s.showZeros?1:0}"/></sheetViews><sheetFormatPr defaultRowHeight="${s.defaultHeight||15}"/><cols>${s.columns.map(c=>`<col min="${c.column+1}" max="${c.column+1}" width="${c.width}" customWidth="1"${c.hidden?' hidden="1"':''}/>`).join('')}</cols><sheetData>${data}</sheetData>${s.merges.length?`<mergeCells count="${s.merges.length}">${s.merges.map(m=>`<mergeCell ref="${sheetXml(m)}"/>`).join('')}</mergeCells>`:''}<printOptions horizontalCentered="${p.horizontalCentered?1:0}" verticalCentered="${p.verticalCentered?1:0}"/><pageMargins left="${p.left}" right="${p.right}" top="${p.top}" bottom="${p.bottom}" header="${p.header}" footer="${p.footer}"/><pageSetup paperSize="${p.paperSize}" scale="${p.scale}" orientation="${flags&2?'portrait':'landscape'}" fitToWidth="${p.fitToWidth}" fitToHeight="${p.fitToHeight}" firstPageNumber="${p.firstPageNumber||1}" useFirstPageNumber="${flags&128?1:0}" horizontalDpi="${p.horizontalDpi}" verticalDpi="${p.verticalDpi}" pageOrder="${flags&1?'overThenDown':'downThenOver'}" blackAndWhite="${flags&8?1:0}" draft="${flags&16?1:0}"/><headerFooter><oddHeader>${sheetXml(p.headerText||'')}</oddHeader><oddFooter>${sheetXml(p.footerText||'')}</oddFooter></headerFooter></worksheet>`;
  if(s.rowBreaks?.length)entries[`xl/worksheets/sheet${i+1}.xml`]=entries[`xl/worksheets/sheet${i+1}.xml`].replace('</worksheet>',`<rowBreaks count="${s.rowBreaks.length}" manualBreakCount="${s.rowBreaks.length}">${s.rowBreaks.map(id=>`<brk id="${id}" min="0" max="16383" man="1"/>`).join('')}</rowBreaks></worksheet>`);
  if(s.shapes?.length){
   const drawing=`drawing${i+1}.xml`,emu=n=>Math.round(n*12700);
   entries['[Content_Types].xml']=entries['[Content_Types].xml'].replace('</Types>',`<Override PartName="/xl/drawings/${drawing}" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/></Types>`);
   entries[`xl/worksheets/_rels/sheet${i+1}.xml.rels`]=`<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdDrawing" Type="${rel}/drawing" Target="../drawings/${drawing}"/></Relationships>`;
   entries[`xl/worksheets/sheet${i+1}.xml`]=entries[`xl/worksheets/sheet${i+1}.xml`].replace('<worksheet xmlns=',`<worksheet xmlns:r="${rel}" xmlns=`).replace('</worksheet>','<drawing r:id="rIdDrawing"/></worksheet>');
   entries[`xl/drawings/${drawing}`]=`<xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main">${s.shapes.map((v,j)=>`<xdr:absoluteAnchor><xdr:pos x="${emu(v.x)}" y="${emu(v.y)}"/><xdr:ext cx="${emu(v.width)}" cy="${emu(v.height)}"/><xdr:sp><xdr:nvSpPr><xdr:cNvPr id="${j+1}" name="문서 제목 ${j+1}"/><xdr:cNvSpPr txBox="1"/></xdr:nvSpPr><xdr:spPr><a:xfrm><a:off x="${emu(v.x)}" y="${emu(v.y)}"/><a:ext cx="${emu(v.width)}" cy="${emu(v.height)}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:solidFill><a:srgbClr val="FFFFFF"/></a:solidFill><a:ln w="7620"><a:solidFill><a:srgbClr val="000000"/></a:solidFill></a:ln><a:effectLst><a:outerShdw blurRad="0" dist="35921" dir="2700000" algn="tl" rotWithShape="0"><a:srgbClr val="B3B3B3"/></a:outerShdw></a:effectLst></xdr:spPr><xdr:txBody><a:bodyPr wrap="none" lIns="0" tIns="0" rIns="0" bIns="0" anchor="ctr"><a:noAutofit/></a:bodyPr><a:lstStyle/><a:p><a:pPr algn="ctr"/><a:r><a:rPr lang="ko-KR" sz="${Math.round(v.size*100)}" spc="${Math.round((v.spacing||0)*100)}"><a:solidFill><a:srgbClr val="000000"/></a:solidFill><a:latin typeface="굴림체"/><a:ea typeface="굴림체"/></a:rPr><a:t>${sheetXml(v.text)}</a:t></a:r><a:endParaRPr lang="ko-KR"/></a:p></xdr:txBody></xdr:sp><xdr:clientData/></xdr:absoluteAnchor>`).join('')}</xdr:wsDr>`;
  }
 }
 return zipStore(entries);
}
